class TemplateError(Exception):
    def __init__(self, line, message=None):
        self.line = line
        if message is None:
            message = f"Template error at line {line}"
        super().__init__(message)


UNDEFINED = object()

_RESERVED = {"and", "or", "not", "true", "false", "none", "in"}
_FILTER_ARGS = {
    "upper": 0,
    "lower": 0,
    "trim": 0,
    "length": 0,
    "first": 0,
    "last": 0,
    "join": 1,
    "truncate": 1,
    "default": 1,
    "raw": 0,
}
_BLOCK_KEYWORDS = {"if", "elif", "else", "endif", "for", "endfor", "set"}


class _ETok:
    __slots__ = ("type", "value", "raw")

    def __init__(self, type, value, raw):
        self.type = type
        self.value = value
        self.raw = raw


class _Lit:
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value


class _Path:
    __slots__ = ("name", "segs")

    def __init__(self, name, segs):
        self.name = name
        self.segs = segs


class _Paren:
    __slots__ = ("expr",)

    def __init__(self, expr):
        self.expr = expr


class _Not:
    __slots__ = ("expr",)

    def __init__(self, expr):
        self.expr = expr


class _BoolOp:
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


class _Compare:
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


class _Filter:
    __slots__ = ("name", "args")

    def __init__(self, name, args):
        self.name = name
        self.args = args


class _FilterChain:
    __slots__ = ("base", "filters")

    def __init__(self, base, filters):
        self.base = base
        self.filters = filters


class _Text:
    __slots__ = ("text",)

    def __init__(self, text):
        self.text = text


class _Output:
    __slots__ = ("expr", "raw")

    def __init__(self, expr, raw):
        self.expr = expr
        self.raw = raw


class _Set:
    __slots__ = ("name", "expr")

    def __init__(self, name, expr):
        self.name = name
        self.expr = expr


class _If:
    __slots__ = ("branches", "else_body")

    def __init__(self, branches, else_body):
        self.branches = branches
        self.else_body = else_body


class _For:
    __slots__ = ("name", "expr", "body", "else_body")

    def __init__(self, name, expr, body, else_body):
        self.name = name
        self.expr = expr
        self.body = body
        self.else_body = else_body


class _Token:
    __slots__ = (
        "type",
        "text",
        "line",
        "trim_left",
        "trim_right",
        "keyword",
        "payload",
        "expr",
        "raw",
    )

    def __init__(
        self,
        type,
        line,
        trim_left=False,
        trim_right=False,
        text=None,
        keyword=None,
        payload=None,
        expr=None,
        raw=False,
    ):
        self.type = type
        self.line = line
        self.trim_left = trim_left
        self.trim_right = trim_right
        self.text = text
        self.keyword = keyword
        self.payload = payload
        self.expr = expr
        self.raw = raw


def _ident_start(ch):
    return ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ch == "_"


def _ident_char(ch):
    return _ident_start(ch) or ("0" <= ch <= "9")


def _tokenize_expr(s, line):
    toks = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        if ch in " \t\n\r\f\v":
            i += 1
            continue

        if ch == '"' or ch == "'":
            j = s.find(ch, i + 1)
            if j == -1:
                raise TemplateError(line, "Unterminated string")
            toks.append(_ETok("STRING", s[i + 1 : j], s[i + 1 : j]))
            i = j + 1
            continue

        if "0" <= ch <= "9":
            j = i
            while j < n and "0" <= s[j] <= "9":
                j += 1
            raw = s[i:j]
            toks.append(_ETok("INT", int(raw), raw))
            i = j
            continue

        if ch == "-" and i + 1 < n and "0" <= s[i + 1] <= "9":
            j = i + 1
            while j < n and "0" <= s[j] <= "9":
                j += 1
            raw = s[i:j]
            toks.append(_ETok("INT", int(raw), raw))
            i = j
            continue

        if _ident_start(ch):
            j = i
            while j < n and _ident_char(s[j]):
                j += 1
            raw = s[i:j]
            toks.append(_ETok("NAME", raw, raw))
            i = j
            continue

        if ch == "=":
            if i + 1 < n and s[i + 1] == "=":
                toks.append(_ETok("OP", "==", "=="))
                i += 2
            else:
                toks.append(_ETok("OP", "=", "="))
                i += 1
            continue

        if ch == "!":
            if i + 1 < n and s[i + 1] == "=":
                toks.append(_ETok("OP", "!=", "!="))
                i += 2
                continue
            raise TemplateError(line, "Unexpected character")

        if ch in "|.(),":
            toks.append(_ETok("OP", ch, ch))
            i += 1
            continue

        raise TemplateError(line, "Unexpected character")

    toks.append(_ETok("EOF", None, None))
    return toks


class _ExprParser:
    def __init__(self, tokens, line):
        self.tokens = tokens
        self.pos = 0
        self.line = line

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def at_end(self):
        return self.tokens[self.pos].type == "EOF"

    def expect_eof(self):
        if not self.at_end():
            raise TemplateError(self.line, "Unexpected token")

    def parse_expression(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.peek().type == "NAME" and self.peek().value == "or":
            self.advance()
            right = self.parse_and()
            left = _BoolOp("or", left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.peek().type == "NAME" and self.peek().value == "and":
            self.advance()
            right = self.parse_not()
            left = _BoolOp("and", left, right)
        return left

    def parse_not(self):
        if self.peek().type == "NAME" and self.peek().value == "not":
            self.advance()
            return _Not(self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_filter()
        tok = self.peek()
        if tok.type == "OP" and tok.value in ("==", "!="):
            op = tok.value
            self.advance()
            right = self.parse_filter()
            tok2 = self.peek()
            if tok2.type == "OP" and tok2.value in ("==", "!="):
                raise TemplateError(self.line, "Chained comparison")
            return _Compare(op, left, right)
        return left

    def parse_filter(self):
        base = self.parse_primary()
        filters = []

        while self.peek().type == "OP" and self.peek().value == "|":
            self.advance()

            name_tok = self.peek()
            if name_tok.type != "NAME":
                raise TemplateError(self.line, "Expected filter name")
            name = name_tok.value
            self.advance()

            args = []
            if self.peek().type == "OP" and self.peek().value == "(":
                self.advance()
                if self.peek().type == "OP" and self.peek().value == ")":
                    self.advance()
                else:
                    args.append(self.parse_expression())
                    while self.peek().type == "OP" and self.peek().value == ",":
                        self.advance()
                        args.append(self.parse_expression())
                    if self.peek().type != "OP" or self.peek().value != ")":
                        raise TemplateError(self.line, "Expected )")
                    self.advance()

            if name not in _FILTER_ARGS:
                raise TemplateError(self.line, "Unknown filter")
            if len(args) != _FILTER_ARGS[name]:
                raise TemplateError(self.line, "Wrong number of filter arguments")

            filters.append(_Filter(name, args))

        if filters:
            return _FilterChain(base, filters)
        return base

    def parse_primary(self):
        tok = self.peek()

        if tok.type == "INT":
            self.advance()
            return _Lit(tok.value)

        if tok.type == "STRING":
            self.advance()
            return _Lit(tok.value)

        if tok.type == "NAME":
            val = tok.value
            if val == "true":
                self.advance()
                return _Lit(True)
            if val == "false":
                self.advance()
                return _Lit(False)
            if val == "none":
                self.advance()
                return _Lit(None)
            if val in _RESERVED:
                raise TemplateError(self.line, "Reserved keyword")

            self.advance()
            segs = []

            while self.peek().type == "OP" and self.peek().value == ".":
                self.advance()
                seg_tok = self.peek()

                if seg_tok.type == "NAME":
                    if seg_tok.value in _RESERVED:
                        raise TemplateError(self.line, "Reserved keyword")
                    segs.append(seg_tok.value)
                    self.advance()
                elif seg_tok.type == "INT":
                    if seg_tok.raw[0] == "-":
                        raise TemplateError(self.line, "Invalid path segment")
                    segs.append(seg_tok.raw)
                    self.advance()
                else:
                    raise TemplateError(self.line, "Invalid path segment")

            return _Path(val, segs)

        if tok.type == "OP" and tok.value == "(":
            self.advance()
            expr = self.parse_expression()
            if self.peek().type != "OP" or self.peek().value != ")":
                raise TemplateError(self.line, "Expected )")
            self.advance()
            return _Paren(expr)

        raise TemplateError(self.line, "Invalid expression")


def _parse_output(inner, line):
    tokens = _tokenize_expr(inner, line)
    parser = _ExprParser(tokens, line)

    if parser.at_end():
        raise TemplateError(line, "Empty output tag")

    expr = parser.parse_expression()
    parser.expect_eof()

    raw = isinstance(expr, _FilterChain) and any(
        f.name == "raw" for f in expr.filters
    )
    return expr, raw


def _parse_block_header(inner, line):
    tokens = _tokenize_expr(inner, line)
    parser = _ExprParser(tokens, line)

    tok = parser.peek()
    if tok.type != "NAME":
        raise TemplateError(line, "Invalid block tag")

    kw = tok.value
    parser.advance()

    if kw not in _BLOCK_KEYWORDS:
        raise TemplateError(line, "Unknown block tag")

    if kw in ("if", "elif"):
        if parser.at_end():
            raise TemplateError(line, "Missing expression")
        expr = parser.parse_expression()
        parser.expect_eof()
        return kw, expr

    if kw in ("else", "endif", "endfor"):
        parser.expect_eof()
        return kw, None

    if kw == "for":
        var_tok = parser.peek()
        if var_tok.type != "NAME":
            raise TemplateError(line, "Missing loop variable")
        var = var_tok.value
        if var in _RESERVED:
            raise TemplateError(line, "Reserved keyword")
        parser.advance()

        in_tok = parser.peek()
        if in_tok.type != "NAME" or in_tok.value != "in":
            raise TemplateError(line, "Missing in")
        parser.advance()

        if parser.at_end():
            raise TemplateError(line, "Missing expression")

        expr = parser.parse_expression()
        parser.expect_eof()
        return kw, (var, expr)

    if kw == "set":
        var_tok = parser.peek()
        if var_tok.type != "NAME":
            raise TemplateError(line, "Missing variable name")
        var = var_tok.value
        if var in _RESERVED:
            raise TemplateError(line, "Reserved keyword")
        parser.advance()

        eq = parser.peek()
        if eq.type != "OP" or eq.value != "=":
            raise TemplateError(line, "Missing =")
        parser.advance()

        if parser.at_end():
            raise TemplateError(line, "Missing expression")

        expr = parser.parse_expression()
        parser.expect_eof()
        return kw, (var, expr)

    raise TemplateError(line, "Invalid block tag")


def _scan_template(template):
    tokens = []
    pos = 0
    n = len(template)

    while pos < n:
        start = n
        opener = None

        for op in ("{{", "{%", "{#"):
            idx = template.find(op, pos)
            if idx != -1 and idx < start:
                start = idx
                opener = op

        if opener is None:
            if pos < n:
                tokens.append(_Token("TEXT", 0, text=template[pos:]))
            break

        if start > pos:
            tokens.append(_Token("TEXT", 0, text=template[pos:start]))

        line = template.count("\n", 0, start) + 1
        closer = {"{{": "}}", "{%": "%}", "{#": "#}"}[opener]
        close = template.find(closer, start + 2)

        if close == -1:
            raise TemplateError(line, "Missing tag closer")

        inner_raw = template[start + 2 : close]

        trim_left = inner_raw.startswith("-")
        inner = inner_raw[1:] if trim_left else inner_raw

        trim_right = inner.endswith("-")
        if trim_right:
            inner = inner[:-1]

        if opener == "{{":
            expr, raw = _parse_output(inner, line)
            tokens.append(
                _Token("OUTPUT", line, trim_left, trim_right, expr=expr, raw=raw)
            )
        elif opener == "{%":
            keyword, payload = _parse_block_header(inner, line)
            tokens.append(
                _Token(
                    "BLOCK",
                    line,
                    trim_left,
                    trim_right,
                    keyword=keyword,
                    payload=payload,
                )
            )
        else:
            tokens.append(_Token("COMMENT", line, trim_left, trim_right))

        pos = close + 2

    return tokens


def _apply_whitespace(tokens):
    for i, tok in enumerate(tokens):
        if tok.type in ("OUTPUT", "BLOCK", "COMMENT"):
            if tok.trim_left and i > 0 and tokens[i - 1].type == "TEXT":
                tokens[i - 1].text = tokens[i - 1].text.rstrip(" \t\n")
            if tok.trim_right and i + 1 < len(tokens) and tokens[i + 1].type == "TEXT":
                tokens[i + 1].text = tokens[i + 1].text.lstrip(" \t\n")


def _parse_if(tokens, i, cond, line):
    branches = []
    else_body = None
    i += 1

    while True:
        body, j, stop_kw, stop_payload = _parse_sequence(
            tokens, i, {"elif", "else", "endif"}
        )

        if stop_kw is None:
            raise TemplateError(line, "Unclosed if")

        if stop_kw == "elif":
            branches.append((cond, body))
            cond = stop_payload
            i = j + 1
        elif stop_kw == "else":
            branches.append((cond, body))
            i = j + 1

            else_body, j2, stop_kw2, _ = _parse_sequence(tokens, i, {"endif"})
            if stop_kw2 is None:
                raise TemplateError(line, "Unclosed if")

            i = j2 + 1
            break
        else:
            branches.append((cond, body))
            i = j + 1
            break

    return _If(branches, else_body), i


def _parse_for(tokens, i, payload, line):
    var, expr = payload
    i += 1

    body, j, stop_kw, _ = _parse_sequence(tokens, i, {"else", "endfor"})
    if stop_kw is None:
        raise TemplateError(line, "Unclosed for")

    else_body = None

    if stop_kw == "else":
        i = j + 1
        else_body, j2, stop_kw2, _ = _parse_sequence(tokens, i, {"endfor"})
        if stop_kw2 is None:
            raise TemplateError(line, "Unclosed for")
        i = j2 + 1
    else:
        i = j + 1

    return _For(var, expr, body, else_body), i


def _parse_sequence(tokens, i, stops):
    nodes = []

    while i < len(tokens):
        tok = tokens[i]

        if tok.type == "TEXT":
            nodes.append(_Text(tok.text))
            i += 1
        elif tok.type == "OUTPUT":
            nodes.append(_Output(tok.expr, tok.raw))
            i += 1
        elif tok.type == "BLOCK":
            kw = tok.keyword
            payload = tok.payload

            if kw in stops:
                return nodes, i, kw, payload

            if kw == "if":
                node, i = _parse_if(tokens, i, payload, tok.line)
                nodes.append(node)
            elif kw == "for":
                node, i = _parse_for(tokens, i, payload, tok.line)
                nodes.append(node)
            elif kw == "set":
                nodes.append(_Set(payload[0], payload[1]))
                i += 1
            else:
                raise TemplateError(tok.line, "Mismatched block tag")
        else:
            i += 1

    return nodes, i, None, None


def _render_value(value):
    if value is UNDEFINED or value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return ", ".join(_render_value(item) for item in value)
    if isinstance(value, dict):
        return "[object]"
    return ""


def _escape(text):
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )


def _truth(value):
    if value is UNDEFINED or value is None:
        return False
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value != 0
    if isinstance(value, str):
        return len(value) > 0
    if isinstance(value, (list, dict)):
        return len(value) > 0
    return False


def _equal(a, b):
    if a is UNDEFINED and b is UNDEFINED:
        return True
    if a is UNDEFINED:
        return b is None
    if b is UNDEFINED:
        return a is None

    if a is None or b is None:
        return a is None and b is None

    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, int) and isinstance(b, int):
        return a == b

    if isinstance(a, str) and isinstance(b, str):
        return a == b

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not _equal(x, y):
                return False
        return True

    if isinstance(a, dict) and isinstance(b, dict):
        if len(a) != len(b):
            return False

        b_items = list(b.items())
        used = [False] * len(b_items)

        for ak, av in a.items():
            found = False
            for idx, (bk, bv) in enumerate(b_items):
                if not used[idx] and _equal(ak, bk) and _equal(av, bv):
                    used[idx] = True
                    found = True
                    break
            if not found:
                return False

        return True

    return False


def _segment(value, seg):
    if value is UNDEFINED:
        return UNDEFINED

    if isinstance(value, dict):
        if seg in value:
            return value[seg]
        return UNDEFINED

    if isinstance(value, list):
        if seg.isdigit():
            idx = int(seg)
            if 0 <= idx < len(value):
                return value[idx]
        return UNDEFINED

    return UNDEFINED


def _apply_filter(value, name, args):
    if name == "upper":
        return _render_value(value).upper()

    if name == "lower":
        return _render_value(value).lower()

    if name == "trim":
        return _render_value(value).strip()

    if name == "length":
        if isinstance(value, str):
            return len(value)
        if isinstance(value, (list, dict)):
            return len(value)
        return 0

    if name == "first":
        if isinstance(value, list) and value:
            return value[0]
        return UNDEFINED

    if name == "last":
        if isinstance(value, list) and value:
            return value[-1]
        return UNDEFINED

    if name == "join":
        sep = _render_value(args[0])
        if isinstance(value, list):
            return sep.join(_render_value(item) for item in value)
        return _render_value(value)

    if name == "truncate":
        text = _render_value(value)
        n = args[0]
        if isinstance(n, int) and not isinstance(n, bool) and n >= 3:
            if len(text) <= n:
                return text
            return text[: n - 3] + "..."
        return text

    if name == "default":
        if value is UNDEFINED or value is None:
            return args[0]
        return value

    if name == "raw":
        return value

    return value


def _eval(node, env, ctx):
    if isinstance(node, _Lit):
        return node.value

    if isinstance(node, _Path):
        name = node.name
        if name in env:
            value = env[name]
        elif isinstance(ctx, dict) and name in ctx:
            value = ctx[name]
        else:
            value = UNDEFINED

        for seg in node.segs:
            value = _segment(value, seg)

        return value

    if isinstance(node, _Paren):
        return _eval(node.expr, env, ctx)

    if isinstance(node, _Not):
        return not _truth(_eval(node.expr, env, ctx))

    if isinstance(node, _BoolOp):
        left = _eval(node.left, env, ctx)
        right = _eval(node.right, env, ctx)
        lt = _truth(left)
        rt = _truth(right)
        if node.op == "or":
            return lt or rt
        return lt and rt

    if isinstance(node, _Compare):
        left = _eval(node.left, env, ctx)
        right = _eval(node.right, env, ctx)
        eq = _equal(left, right)
        if node.op == "==":
            return eq
        return not eq

    if isinstance(node, _FilterChain):
        value = _eval(node.base, env, ctx)
        for f in node.filters:
            arg_values = [_eval(arg, env, ctx) for arg in f.args]
            value = _apply_filter(value, f.name, arg_values)
        return value

    return UNDEFINED


def _render_nodes(nodes, env, ctx):
    out = []

    for node in nodes:
        if isinstance(node, _Text):
            out.append(node.text)

        elif isinstance(node, _Output):
            value = _eval(node.expr, env, ctx)
            text = _render_value(value)
            if not node.raw:
                text = _escape(text)
            out.append(text)

        elif isinstance(node, _Set):
            env[node.name] = _eval(node.expr, env, ctx)

        elif isinstance(node, _If):
            rendered = False
            for cond, body in node.branches:
                if _truth(_eval(cond, env, ctx)):
                    out.append(_render_nodes(body, env, ctx))
                    rendered = True
                    break
            if not rendered and node.else_body is not None:
                out.append(_render_nodes(node.else_body, env, ctx))

        elif isinstance(node, _For):
            iterable = _eval(node.expr, env, ctx)

            if isinstance(iterable, list):
                items = iterable
            elif isinstance(iterable, dict):
                items = list(iterable.keys())
            else:
                items = []

            saved = env.copy()

            if items:
                length = len(items)
                for idx, item in enumerate(items):
                    env[node.name] = item
                    env["loop"] = {
                        "index": idx + 1,
                        "index0": idx,
                        "first": idx == 0,
                        "last": idx == length - 1,
                        "length": length,
                    }
                    out.append(_render_nodes(node.body, env, ctx))
            else:
                if node.else_body is not None:
                    out.append(_render_nodes(node.else_body, env, ctx))

            env.clear()
            env.update(saved)

    return "".join(out)


def render(template: str, ctx: dict) -> str:
    if not isinstance(ctx, dict):
        ctx = {}

    tokens = _scan_template(template)
    _apply_whitespace(tokens)

    seq = []
    for tok in tokens:
        if tok.type == "COMMENT":
            continue
        if tok.type == "TEXT" and tok.text == "":
            continue
        seq.append(tok)

    nodes, _, _, _ = _parse_sequence(seq, 0, set())
    return _render_nodes(nodes, {}, ctx)
